node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check the charging stand's specs_json and description more carefully
const row = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-2028EE'\").get();
console.log('Full record:', JSON.stringify(row, null, 2));

// Also search warranties or any other table for TechPhone
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
for (const t of tables) {
  try {
    const r = db.prepare('SELECT * FROM ' + t.name + ' LIMIT 1').get();
    if (r) {
      const cols = Object.keys(r);
      for (const col of cols) {
        const found = db.prepare('SELECT COUNT(*) as cnt FROM ' + t.name + ' WHERE CAST(' + col + ' AS TEXT) LIKE \"%TechPhone%\"').get();
        if (found.cnt > 0) {
          console.log('Found TechPhone in', t.name + '.' + col);
        }
      }
    }
  } catch(e) {}
}
console.log('Done searching all tables.');
"

